"""Rules for names generated by the application."""

from __future__ import annotations

import re
from pathlib import Path
import unicodedata


def normalize_generated_stem(value, fallback="document"):
    """Return a safe basename stem for files created by the application."""
    text = unicodedata.normalize("NFKD", str(value))
    text = "".join(char for char in text if not unicodedata.combining(char))
    text = text.replace("–", "-").replace("—", "-").replace("−", "-")
    text = text.encode("ascii", "ignore").decode("ascii")
    text = re.sub(r"[^A-Za-z0-9 _-]+", "", text)
    text = re.sub(r"[ ]+", " ", text).strip(" .-_")
    if not text:
        text = fallback
    if text.upper() in {"CON", "PRN", "AUX", "NUL"} or re.fullmatch(r"(COM|LPT)[1-9]", text.upper()):
        text = f"_{text}"
    return text


def generated_sidecar(path, suffix):
    """Return the normalized path for an application-created sidecar file."""
    path = Path(path)
    safe = path.with_name(f"{normalize_generated_stem(path.stem)}{suffix}")
    legacy = path.with_suffix(suffix)
    if legacy != safe and legacy.is_file() and not safe.exists():
        return legacy
    return safe


def suggested_output(infile, outlang):
    """Return the normalized default PDF output path."""
    language = str(outlang).strip().casefold()
    language = re.sub(r"[^\w-]", "_", language)
    infile = Path(infile)
    stem = normalize_generated_stem(infile.stem)
    return infile.with_name(f"{stem}-{language}-layout.pdf")
